"use client";
import { ShaderSurface, type ShaderSurfaceOptions } from "./shader-surface";
export interface DitheringProps
  extends Pick<
    ShaderSurfaceOptions,
    "children" | "className" | "style" | "height" | "alt" | "duration" | "maxDpr" | "onReady"
  > {
  image: string;
  dotSize?: number;
  darkColor?: string;
  lightColor?: string;
  lensRadius?: number;
}
/** Ordered Bayer conversion with a smooth pointer lens that restores the original colors. */
export function Dithering({
  dotSize = 3,
  darkColor = "#101010",
  lightColor = "#f2f1eb",
  lensRadius = 130,
  ...props
}: DitheringProps) {
  return (
    <ShaderSurface
      kind="dither"
      scale={dotSize}
      radius={lensRadius}
      colors={[darkColor, lightColor]}
      {...props}
    />
  );
}
